import React from "react";
import { Image } from "../../atoms/Image/Image";
import { CSS } from "../../../stitches.config";

// Erigon's otter mark (erigon.tech favicon), 64x64.
const SRC =
  "data:image/png;base64,";

export type ErigonIconProps = {
  size?: number;
  className?: string;
  css?: CSS;
  alt?: string;
};

/** Bundled Erigon mark for PeerClientIcons (ships in dist). */
export const ErigonIcon: React.FC<ErigonIconProps> = ({
  size = 18,
  className,
  css,
  alt = "erigon",
}) => (
  <Image
    src={SRC}
    alt={alt}
    className={className}
    css={{ width: size, height: size, objectFit: "contain", ...css }}
  />
);

ErigonIcon.displayName = "ErigonIcon";
