import React from "react";
import { NethermindIcon } from "./NethermindIcon";
import { CSS } from "../../../stitches.config";

export type PlutoIconProps = {
  size?: number;
  className?: string;
  css?: CSS;
  alt?: string;
};

/**
 * Pluto (NethermindEth/pluto), Nethermind's Rust distributed validator
 * client, a Charon alternative. Uses the Nethermind mark until Pluto has its
 * own.
 */
export const PlutoIcon: React.FC<PlutoIconProps> = ({
  alt = "Pluto",
  ...props
}) => <NethermindIcon alt={alt} {...props} />;

PlutoIcon.displayName = "PlutoIcon";
