import React from "react";
import { Image } from "../../atoms/Image/Image";
import { CSS } from "../../../stitches.config";

// The dinosaur head cropped from ethrex's logo (lambdaclass/ethrex
// assets/ethrex_logo.png, Apache-2.0), 64x64.
const SRC =
  "data:image/png;base64,";

export type EthrexIconProps = {
  size?: number;
  className?: string;
  css?: CSS;
  alt?: string;
};

/** Bundled ethrex mark for PeerClientIcons (ships in dist). */
export const EthrexIcon: React.FC<EthrexIconProps> = ({
  size = 18,
  className,
  css,
  alt = "ethrex",
}) => (
  <Image
    src={SRC}
    alt={alt}
    className={className}
    css={{
      width: size,
      height: size,
      objectFit: "contain",
      borderRadius: "3px",
      ...css,
    }}
  />
);

EthrexIcon.displayName = "EthrexIcon";
