import React from "react";
import { Image } from "../../atoms/Image/Image";
import { CSS } from "../../../stitches.config";

// Lodestar's own star mark (chainsafe.github.io/lodestar favicon), not the
// ChainSafe company logo. 64x64.
const SRC =
  "data:image/png;base64,";

export type LodestarIconProps = {
  size?: number;
  className?: string;
  css?: CSS;
  alt?: string;
};

/** Bundled lodestar mark for PeerClientIcons (ships in dist). */
export const LodestarIcon: React.FC<LodestarIconProps> = ({
  size = 18,
  className,
  css,
  alt = "lodestar",
}) => (
  <Image
    src={SRC}
    alt={alt}
    className={className}
    css={{ width: size, height: size, objectFit: "contain", ...css }}
  />
);

LodestarIcon.displayName = "LodestarIcon";
