import React from "react";
import { Image } from "../../atoms/Image/Image";
import { CSS } from "../../../stitches.config";

const SRC =
  "data:image/png;base64,";

export type NethermindIconProps = {
  size?: number;
  className?: string;
  css?: CSS;
  alt?: string;
};

/** Bundled nethermind mark for PeerClientIcons (ships in dist). */
export const NethermindIcon: React.FC<NethermindIconProps> = ({
  size = 18,
  className,
  css,
  alt = "nethermind",
}) => (
  <Image
    src={SRC}
    alt={alt}
    className={className}
    css={{ width: size, height: size, objectFit: "contain", ...css }}
  />
);

NethermindIcon.displayName = "NethermindIcon";
