import React from "react";
import { Image } from "../../atoms/Image/Image";
import { CSS } from "../../../stitches.config";

const SRC =
  "data:image/png;base64,";

export type TekuIconProps = {
  size?: number;
  className?: string;
  css?: CSS;
  alt?: string;
};

/** Bundled teku mark for PeerClientIcons (ships in dist). */
export const TekuIcon: React.FC<TekuIconProps> = ({
  size = 18,
  className,
  css,
  alt = "teku",
}) => (
  <Image
    src={SRC}
    alt={alt}
    className={className}
    css={{ width: size, height: size, objectFit: "contain", ...css }}
  />
);

TekuIcon.displayName = "TekuIcon";
